import {adminCatalog,adminOptions,cleanAdmin,resolveAdmin} from './admin-boundaries.js?v=admin-20261017';
export function cleanBoundary(value){
 if(!value)return null;if(value.type==='admin-2022')return {...cleanAdmin(value),label:String(value.label||'').slice(0,300)};const u=new URL(value.url);if(u.protocol!=='https:'||u.username||u.password||u.search||u.hash||! /\/(FeatureServer|MapServer)\/\d+$/i.test(u.pathname)||typeof value.field!=='string'||!value.field||!Number.isSafeInteger(value.id)||typeof value.label!=='string')throw Error('Invalid saved boundary. Choose the boundary again.');return {url:u.href,field:value.field,id:value.id,label:value.label.slice(0,300)};
}
export function polygonParams(geometry,relation='esriSpatialRelIntersects'){
 if(!geometry?.rings?.length||!geometry.spatialReference||geometry.rings.some(r=>!Array.isArray(r)||r.length<4||r.some(p=>!Array.isArray(p)||p.length<2||!p.slice(0,2).every(Number.isFinite))))throw Error('The selected boundary has no readable polygon. Monitoring was not started.');return {geometry:JSON.stringify(geometry),geometryType:'esriGeometryPolygon',inSR:JSON.stringify(geometry.spatialReference),spatialRel:relation};
}
export async function boundaryGeometry(api,scope){const s=cleanBoundary(scope);if(s.type==='admin-2022')return (await resolveAdmin(s)).geometry;const r=await api.request(s.url+'/query',{objectIds:s.id,outFields:s.field,returnGeometry:true,outSR:4326});if(r.exceededTransferLimit||r.features?.length!==1)throw Error('Selected boundary is unavailable. Choose it again.');const geometry={...r.features[0].geometry,spatialReference:r.features[0].geometry?.spatialReference||r.spatialReference};polygonParams(geometry);return geometry;}
export async function scopedIds(api,url,params){if(!params)return api.ids(url,'1=1');const r=await api.request(url+'/query',{where:'1=1',returnIdsOnly:true,...params});if(r.exceededTransferLimit||!Array.isArray(r.objectIds))throw Error('Boundary query did not return a complete ID list. No unrestricted scan was used.');return [...new Set(r.objectIds)].sort((a,b)=>a-b);}
export function attachBoundary({$,auth,changed,action}){
 let meta=null,loadedUrl='',scope=null,pending=false,catalog=null;const status=t=>$('boundary-status').textContent=t;
 const reset=()=>{pending=false;scope=null;for(const level of ['province','district','sector'])$('admin-'+level).replaceChildren(new Option(level==='province'?'All provinces':'All '+level+'s',''));meta=null;loadedUrl='';$('boundary-name').replaceChildren(new Option('Load a boundary layer first',''));$('boundary-field').replaceChildren();$('boundary-preview').replaceChildren();status('All accessible areas. Choose a boundary to restrict all three monitoring spaces.');};
 $('boundary-clear').onclick=()=>{reset();changed();};
 $('boundary-load').onclick=()=>action(async()=>{changed();reset();pending=true;const url=$('boundary-url').value.trim();cleanBoundary({url,field:'id',id:0,label:''});meta=await auth().request(url);if(meta.geometryType!=='esriGeometryPolygon')throw Error('Choose a polygon boundary layer, such as district boundaries.');meta.objectIdField||=meta.fields?.find(f=>f.type==='esriFieldTypeOID')?.name;if(!meta.objectIdField)throw Error('Boundary layer has no object ID field.');loadedUrl=url;for(const f of meta.fields.filter(f=>f.type==='esriFieldTypeString'))$('boundary-field').add(new Option((f.alias||f.name)+' ['+f.name+']',f.name));status('Choose the district/name field, then Load boundary names.');});
 $('boundary-names').onclick=()=>action(async()=>{if(!meta||!loadedUrl)throw Error('Load a boundary layer first.');changed();pending=true;scope=null;const field=$('boundary-field').value;if(!field)throw Error('Choose a boundary name field.');const api=auth(),ids=await api.ids(loadedUrl);if(ids.length>10000)throw Error('Boundary layer has more than 10,000 areas. Use a district-level layer.');const options=[];for(let i=0;i<ids.length;i+=100){const part=ids.slice(i,i+100),r=await api.request(loadedUrl+'/query',{objectIds:part.join(','),outFields:[meta.objectIdField,field].join(','),returnGeometry:false});if(r.exceededTransferLimit||r.features?.length!==part.length)throw Error('Boundary names are incomplete. Reload the layer.');for(const f of r.features)options.push(new Option(String(f.attributes[field]??'Unnamed boundary')+' ['+f.attributes[meta.objectIdField]+']',String(f.attributes[meta.objectIdField])));}options.sort((a,b)=>a.text.localeCompare(b.text));$('boundary-name').replaceChildren(new Option('Choose a boundary…',''),...options);status(options.length+' boundaries loaded. Select the area you want to monitor.');});
 $('boundary-field').onchange=()=>{pending=true;scope=null;$('boundary-name').replaceChildren(new Option('Load boundary names',''));$('boundary-preview').replaceChildren();changed();status('Name field changed. Reload boundary names.');};
 $('boundary-name').onchange=()=>action(async()=>{scope=null;pending=true;changed();const select=$('boundary-name');if(!select.value){status('Choose a boundary, or click Monitor all areas.');return;}const candidate=cleanBoundary({url:loadedUrl,field:$('boundary-field').value,id:Number(select.value),label:select.selectedOptions[0].text}),geometry=await boundaryGeometry(auth(),candidate);scope=candidate;pending=false;preview(geometry);status('Monitoring boundary: '+scope.label+'. Devices and junctions inside or touching the boundary, and lines crossing it, are included.');});
 function preview(g){let x=Infinity,y=Infinity,xmax=-Infinity,ymax=-Infinity;for(const ring of g.rings)for(const p of ring){x=Math.min(x,p[0]);y=Math.min(y,p[1]);xmax=Math.max(xmax,p[0]);ymax=Math.max(ymax,p[1]);}const w=xmax-x,h=ymax-y,svg=$('boundary-preview');svg.setAttribute('viewBox',[x-0.01,-y-h-0.01,w+0.02,h+0.02].join(' '));const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d',g.rings.map(r=>'M'+r.map(p=>p[0]+','+(-p[1])).join('L')+'Z').join(''));path.setAttribute('fill','#d4e9df');path.setAttribute('fill-rule','evenodd');path.setAttribute('stroke','#17634e');path.setAttribute('stroke-width',String(Math.max(w,h)/200));svg.replaceChildren(path);}
 function fill(level,records){$('admin-'+level).replaceChildren(new Option('All '+level+'s',''),...records.map(r=>new Option(r.name,r.id)));}
 async function loadAdmin(){catalog=await adminCatalog();fill('province',adminOptions(catalog,'province'));fill('district',[]);fill('sector',[]);status('2022 boundaries loaded: choose Province, then District and optionally Sector.');}
 $('admin-load').onclick=()=>action(async()=>{changed();reset();pending=true;await loadAdmin();pending=false;changed();});
 for(const level of ['province','district','sector'])$('admin-'+level).onchange=()=>action(async()=>{scope=null;pending=true;changed();$('boundary-preview').replaceChildren();if(!catalog)throw Error('Load administrative boundaries first.');const province=$('admin-province').value;if(level==='province'){fill('district',province?adminOptions(catalog,'district',province):[]);fill('sector',[]);}const district=$('admin-district').value;if(level==='district')fill('sector',district?adminOptions(catalog,'sector',province,district):[]);const sector=$('admin-sector').value;const chosen=sector?'sector':district?'district':province?'province':null;if(!chosen){pending=false;status('All accessible areas.');changed();return;}const result=await resolveAdmin({type:'admin-2022',level:chosen,id:sector||district||province});polygonParams(result.geometry);scope=result.scope;pending=false;preview(result.geometry);status('Monitoring boundary: '+scope.label+'. Source: supplied Boundaries_2022.gdb (2022). Features touching or crossing the boundary are included.');changed();});
 $('boundary-source').onchange=()=>{$('boundary-url').value=$('boundary-source').value;pending=true;scope=null;changed();status('Click Load boundary layer to use this source.');};
 reset();return {snapshot:()=>{if(pending)throw Error('Finish choosing your monitoring boundary before saving.');return scope;},async params(){if(pending)throw Error('Finish choosing a boundary, or explicitly click Monitor all areas.');return scope?polygonParams(await boundaryGeometry(auth(),scope)):null;},async restore(value){reset();if(!value)return;pending=true;let candidate=cleanBoundary(value);if(candidate.type==='admin-2022'){const r=await resolveAdmin(candidate);await loadAdmin();const province=candidate.level==='province'?candidate.id:r.record.provinceId;$('admin-province').value=province;fill('district',adminOptions(catalog,'district',province));const district=candidate.level==='district'?candidate.id:r.record.districtId;if(district){$('admin-district').value=district;fill('sector',adminOptions(catalog,'sector',province,district));}if(candidate.level==='sector')$('admin-sector').value=candidate.id;candidate=r.scope;}const g=await boundaryGeometry(auth(),candidate);scope=candidate;pending=false;if(candidate.url)$('boundary-url').value=candidate.url;preview(g);status('Restored monitoring boundary: '+candidate.label+'.');},reset};
}
